{
  "title": "神秘古村的秘密",
  "scene": "你站在一座古老的村庄前，周围弥漫着一丝不可言喻的神秘气息。村庄里光线昏暗，偶尔传来阵阵奇怪的声音。村民们神色紧张，低声交谈，似乎在讨论一件令人心寒的大事。靠近村子中央的老槐树下，隐约可见一块石碑，上面似乎有着被尘封的古老文字。",
  "goal": "揭开古村的秘密，找出村民们心中隐藏的恐惧。",
  "choices": [
    {
      "id": "A",
      "text": "走近老槐树，试图读懂石碑上的文字。",
      "outcome": "石碑上的文字模糊不清，无法辨认。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "询问一个貌似知道内情的村民，但被他以奇怪的眼神回避。",
      "outcome": "村民显得非常警惕，甚至试图接近人群，你只能放弃。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "观察四周，寻找可能隐藏线索的其他地方。",
      "outcome": "在村口废弃的神庙里，你发现了一些发黄的卷轴，隐约能辨认出里面记载着关于某种古老仪式的信息。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
